function unique(values) {
  return [...new Set((values || []).map(v => String(v || "").trim()).filter(Boolean))];
}

function cleanHtml(value) {
  return String(value || "")
    .replace(/<script[\s\S]*?<\/script>/gi, " ")
    .replace(/<style[\s\S]*?<\/style>/gi, " ")
    .replace(/<[^>]*>/g, " ")
    .replace(/&nbsp;/g, " ")
    .replace(/&amp;/g, "&")
    .replace(/&#8217;/g, "'")
    .replace(/&#8220;/g, '"')
    .replace(/&#8221;/g, '"')
    .replace(/&#8211;|&#8212;/g, "-")
    .replace(/\s+/g, " ")
    .trim();
}

function truncate(value, max = 700) {
  const text = cleanHtml(value);
  return text.length > max ? text.slice(0, max - 3).trim() + "..." : text;
}

function extractUrls(text) {
  const matches = String(text || "").match(/\bhttps?:\/\/[^\s"'<>),]+/gi) || [];
  return unique(matches.map(u => u.replace(/[.,;:!?]+$/g, "")));
}

function extractEmails(text) {
  return unique(String(text || "").match(/\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b/gi) || []);
}

function extractIps(text) {
  const ipv4 = String(text || "").match(/\b(?:(?:25[0-5]|2[0-4]\d|1?\d?\d)\.){3}(?:25[0-5]|2[0-4]\d|1?\d?\d)\b/g) || [];
  const ipv6 = String(text || "").match(/\b(?:[A-F0-9]{1,4}:){2,7}[A-F0-9]{1,4}\b/gi) || [];
  return unique([...ipv4, ...ipv6]);
}

function extractHashes(text) {
  const md5 = String(text || "").match(/\b[a-fA-F0-9]{32}\b/g) || [];
  const sha1 = String(text || "").match(/\b[a-fA-F0-9]{40}\b/g) || [];
  const sha256 = String(text || "").match(/\b[a-fA-F0-9]{64}\b/g) || [];
  return unique([...md5, ...sha1, ...sha256]);
}

function extractCves(text) {
  return unique(String(text || "").match(/\bCVE-\d{4}-\d{4,7}\b/gi) || []).map(c => c.toUpperCase());
}

function extractDomains(text, urls) {
  const fromUrls = [];
  for (const url of urls || []) {
    try {
      const host = new URL(url).hostname.replace(/^www\./, "");
      if (host) fromUrls.push(host);
    } catch (e) {}
  }

  const candidates = String(text || "").match(/\b(?:[a-zA-Z0-9-]{2,63}\.)+[a-zA-Z]{2,24}\b/g) || [];
  const blocked = new Set([
    "krebsonsecurity.com", "nist.gov", "nvd.nist.gov", "cisa.gov", "github.com",
    "microsoft.com", "google.com", "apple.com", "mozilla.org", "oracle.com",
    "example.com", "example.org", "w3.org"
  ]);

  const cleaned = candidates
    .map(d => d.toLowerCase().replace(/^www\./, "").replace(/[.,;:!?]+$/g, ""))
    .filter(d => !blocked.has(d))
    .filter(d => !/^\d+\.\d+\.\d+\.\d+$/.test(d));

  return unique([...fromUrls, ...cleaned]);
}

function extractAffectedSoftware(text) {
  const software = [];

  // CPE strings from NVD content, if present.
  const cpes = String(text || "").match(/cpe:2\.3:[aho]:[^:\s]+:[^:\s]+/gi) || [];
  for (const cpe of cpes) {
    const parts = cpe.split(":");
    if (parts.length >= 5) {
      const vendor = parts[3].replace(/_/g, " ");
      const product = parts[4].replace(/_/g, " ");
      if (vendor && product) software.push(`${vendor} ${product}`);
    }
  }

  const keywords = [
    "Windows Server", "Microsoft Windows", "Microsoft Office", "Microsoft Exchange",
    "Apache Tomcat", "Apache Struts", "Apache HTTP Server", "OpenSSL",
    "Cisco IOS", "Cisco ASA", "Fortinet", "FortiOS", "Palo Alto", "PAN-OS",
    "Ivanti", "MOVEit", "WordPress", "Drupal", "Joomla", "VMware", "vCenter",
    "Linux Kernel", "Ubuntu", "Debian", "Chrome", "Firefox", "Edge", "Android",
    "iOS", "macOS", "Docker", "Kubernetes", "Redis", "Oracle", "SAP", "Adobe Reader"
  ];

  const lower = String(text || "").toLowerCase();
  for (const keyword of keywords) {
    if (lower.includes(keyword.toLowerCase())) software.push(keyword);
  }

  return unique(software).slice(0, 20);
}

function detectSeverity(text) {
  const lower = String(text || "").toLowerCase();

  const cvssScores = [...String(text || "").matchAll(/cvss[^0-9]{0,20}([0-9]\.[0-9]|10\.0)/gi)]
    .map(m => Number(m[1]))
    .filter(n => !Number.isNaN(n));

  const maxCvss = cvssScores.length ? Math.max(...cvssScores) : null;
  if (maxCvss !== null) {
    if (maxCvss >= 9.0) return "Critical";
    if (maxCvss >= 7.0) return "High";
    if (maxCvss >= 4.0) return "Medium";
    return "Low";
  }

  if (lower.includes("critical") || lower.includes("zero-day") || lower.includes("0-day") || lower.includes("remote code execution") || lower.includes("rce")) return "Critical";
  if (lower.includes("ransomware") || lower.includes("credential theft") || lower.includes("exploited in the wild") || lower.includes("active exploitation")) return "High";
  if (lower.includes("malware") || lower.includes("phishing") || lower.includes("botnet") || lower.includes("exploit")) return "Medium";
  return "Unknown";
}

function detectAttackType(text) {
  const lower = String(text || "").toLowerCase();

  const types = [];
  if (lower.includes("phishing") || lower.includes("social engineering")) types.push("Phishing/Social Engineering");
  if (lower.includes("ransomware")) types.push("Ransomware");
  if (lower.includes("malware") || lower.includes("trojan") || lower.includes("backdoor") || lower.includes("worm")) types.push("Malware");
  if (lower.includes("botnet")) types.push("Botnet");
  if (lower.includes("credential") || lower.includes("password") || lower.includes("infostealer") || lower.includes("stealer")) types.push("Credential Theft");
  if (lower.includes("remote code execution") || lower.includes("rce") || lower.includes("exploit") || lower.includes("vulnerability")) types.push("Vulnerability Exploit");
  if (lower.includes("ddos") || lower.includes("denial-of-service") || lower.includes("denial of service")) types.push("DDoS/DoS");
  if (lower.includes("data breach") || lower.includes("breach") || lower.includes("exfiltration")) types.push("Data Breach/Exfiltration");

  return unique(types).join(", ") || "Unknown";
}

function buildSummary(title, source, text, cves) {
  const body = cleanHtml(text);
  const firstSentences = body
    .split(/(?<=[.!?])\s+/)
    .filter(Boolean)
    .slice(0, 2)
    .join(" ");

  if (String(source || "").toLowerCase().includes("nvd") || cves.length > 0) {
    const cvePrefix = cves.length ? `${cves.slice(0, 3).join(", ")} - ` : "";
    return truncate(`${cvePrefix}${title}. ${firstSentences || body}`, 900);
  }

  return truncate(`${title}. ${firstSentences || body}`, 900);
}

function recommendedActions({severity, attackType, cves, ips, domains, urls, hashes, emails}) {
  const actions = [];

  if (cves.length) actions.push("Prioritize patching and vulnerability validation for the listed CVE ID(s).");
  if (ips.length || domains.length || urls.length) actions.push("Check firewall, proxy, DNS, and SIEM logs for matches to the extracted network indicators.");
  if (hashes.length) actions.push("Search EDR/AV telemetry for matching file hashes.");
  if (emails.length) actions.push("Review mail gateway and user inbox logs for matching email indicators.");
  if (/Critical|High/i.test(severity)) actions.push("Escalate for analyst review because the severity is high or critical.");
  if (/Phishing/i.test(attackType)) actions.push("Add related URLs/domains to email security and web filtering blocklists after validation.");
  if (/Ransomware|Malware/i.test(attackType)) actions.push("Hunt for suspicious process execution, persistence, and lateral movement activity.");

  if (!actions.length) {
    actions.push("Review the article/CVE details manually and validate any indicators before blocking.");
  }

  return actions.join("\n");
}

return items.map(item => {
  const fields = item.json.fields || {};

  const title = fields["Title"] || "";
  const source = fields["Source"] || "";
  const url = fields["URL"] || "";
  const rawDescription = fields["Raw Description"] || "";
  const rawContent = fields["Raw Content"] || "";
  const externalId = fields["External ID"] || "";
  const existingTags = fields["Tags"] || "";
  const threatId = fields["Threat ID"] || externalId || "";

  const combinedText = [
    title,
    source,
    url,
    rawDescription,
    rawContent,
    externalId,
    existingTags
  ].join("\n");

  const urls = extractUrls(combinedText);
  const emails = extractEmails(combinedText);
  const ips = extractIps(combinedText);
  const hashes = extractHashes(combinedText);
  const cves = extractCves(combinedText);
  const domains = extractDomains(combinedText, urls);
  const affectedSoftware = extractAffectedSoftware(combinedText);
  const severity = detectSeverity(combinedText);
  const attackType = detectAttackType(combinedText);
  const summary = buildSummary(title, source, rawDescription || rawContent, cves);

  const tags = unique([
    ...String(existingTags || "").split(",").map(t => t.trim()).filter(Boolean),
    source && source.toLowerCase().includes("krebs") ? "security-blog" : "",
    source && source.toLowerCase().includes("nvd") ? "cve" : "",
    attackType !== "Unknown" ? attackType.toLowerCase().replace(/[^a-z0-9]+/g, "-") : ""
  ]);

  const actions = recommendedActions({severity, attackType, cves, ips, domains, urls, hashes, emails});

  return {
    json: {
      airtable_record_id: item.json.id,
      threat_id: threatId,
      title,
      source,
      url,
      raw_description: rawDescription,
      raw_content: rawContent,
      summary,
      severity_level: severity,
      attack_type: attackType,
      affected_software: affectedSoftware.join(", "),
      cve_ids: cves.join(", "),
      tags: tags.join(", "),
      recommended_actions: actions,
      processing_status: "Enriched",
      last_processed: new Date().toISOString(),
      ai_raw_response: "No Flowise/Groq used. Summary and IOCs generated with deterministic n8n JavaScript extraction rules.",
      iocs: {
        ips,
        domains,
        urls,
        hashes,
        emails
      },
      ioc_count: ips.length + domains.length + urls.length + hashes.length + emails.length + cves.length,
      "IOC IPs": ips.join(", "),
      "IOC Domains": domains.join(", "),
      "IOC URLs": urls.join(", "),
      "IOC Hashes": hashes.join(", "),
      "IOC Emails": emails.join(", ")
    }
  };
});

const out = [];

function cleanIocValue(value) {
  return String(value || "").trim();
}

function shouldSkipIoc(value) {
  const cleanValue = cleanIocValue(value);

  if (!cleanValue) return true;

  const weakValues = [
    "suspicious domains",
    "suspicious domain",
    "unknown",
    "n/a",
    "none",
    "not provided",
    "not specified"
  ];

  return weakValues.includes(cleanValue.toLowerCase());
}

function addIoc(data, value, type) {
  const cleanValue = cleanIocValue(value);

  if (shouldSkipIoc(cleanValue)) return;

  const cleanType = String(type || "Other").trim();
  const threatKey = data.airtable_record_id || data.threat_id || "unknown-threat";
  const iocKey = `${threatKey}|${cleanType}|${cleanValue.toLowerCase()}`;
  const now = new Date().toISOString();

  out.push({
    json: {
      "IOC Key": iocKey,
      "IOC Value": cleanValue,
      "IOC Type": cleanType,
      "Source": data.source || "",
      "Threat Record ID": data.airtable_record_id || "",
      "Threat ID": data.threat_id || "",
      "Threat Title": data.title || "",
      "Confidence": 70,
      "First Seen": now,
      "Last Seen": now,
      "Notes": `Extracted by no-Flowise n8n IOC extractor from ${data.source || "unknown source"}`
    }
  });
}

for (const item of items) {
  const data = item.json;
  const iocs = data.iocs || {};

  if (Array.isArray(iocs.ips)) {
    for (const ip of iocs.ips) addIoc(data, ip, "IP");
  }

  if (Array.isArray(iocs.domains)) {
    for (const domain of iocs.domains) addIoc(data, domain, "Domain");
  }

  if (Array.isArray(iocs.urls)) {
    for (const url of iocs.urls) addIoc(data, url, "URL");
  }

  if (Array.isArray(iocs.hashes)) {
    for (const hash of iocs.hashes) addIoc(data, hash, "File Hash");
  }

  if (Array.isArray(iocs.emails)) {
    for (const email of iocs.emails) addIoc(data, email, "Email");
  }

  if (data.cve_ids) {
    const cves = String(data.cve_ids)
      .split(",")
      .map(cve => cve.trim())
      .filter(Boolean);

    for (const cve of cves) {
      addIoc(data, cve, "CVE");
    }
  }
}

return out;
